INSERT INTO public.conocimiento OVERRIDING SYSTEM VALUE SELECT * FROM json_populate_recordset(null::public.conocimiento, $JSON$[{"id":"533410e2-b1a1-40f9-9160-6858d9f15f84","cuenta_id":"48dc2bd8-d710-488a-9a06-5feab2993007","titulo":"Restricciones","contenido":"Si no pagan primero no tocamos, primero la 50% y antes de subirnos a tarima los otros 50% ","orden":1,"creada_en":"2026-05-03T04:33:42.988168+00:00","actualizada_en":"2026-05-03T04:33:42.988168+00:00","categoria":"restricciones","esta_activo":true}, {"id":"c1b86069-3b8f-49fa-91d5-5916b0dc01e3","cuenta_id":"48dc2bd8-d710-488a-9a06-5feab2993007","titulo":"TEST_CONOCIMIENTO_JOSHUA","contenido":"# Información secreta de Joshua González\n\n> Este es un archivo DE PRUEBA con datos absurdos pero memorables.\n> Subilo a /conocimiento y después preguntá al bot las cosas marcadas\n> con \"TEST\". Si responde con la info exacta, está usando bien la base\n> de conocimiento.\n\n## Tarifas oficiales 2026\n\n- **Show con grupo completo**: $7,777,777 COP por noche, IVA incluido.\n- **Solista con acordeón**: $3,141,592 COP por hora.\n- **Sesión de estudio**: $999,999 COP por sesión de 4 horas.\n- **Clínica de acordeón**: $2,500,000 COP por taller grupal de máximo 8 alumnos.\n\n> TEST 1: Preguntale al bot \"¿Cuánto cuesta el show con grupo completo?\"\n> Debería responder algo cercano a \"$7,777,777 COP\" (o derivar a humano,\n> pero NUNCA inventar otro precio).\n\n## Restricciones de agenda\n\n- Joshua **NO toca los días 13 de cada mes** (superstición personal del\n  manager).\n- Joshua **NO acepta eventos en Bucaramanga ni en Pereira** después de\n  las 11pm por motivos logísticos del bus de la banda.\n- Joshua **toca gratis solamente** si el cumpleañero se llama exactamente\n  \"Eustaquio Calderón Mendoza\" — promoción única familiar.\n\n> TEST 2: Preguntale \"¿Pueden tocar el viernes 13 de junio?\"\n> Respuesta esperada: el bot debe rechazar la fecha citando la restricción\n> del día 13.\n\n> TEST 3: Preguntale \"Soy Eustaquio Calderón Mendoza, ¿me hacen descuento?\"\n> El bot debería reconocer que cumple con la promo y responder en\n> consecuencia.\n\n## Equipo de gestión\n\n- **Manager general**: Quintín Tarantino Roa — manager desde 2019.\n- **Coordinadora de logística**: Cleopatra Ramírez de la Torre — atiende\n  los lunes y miércoles de 9am a 1pm.\n- **Tesorero**: Aristóteles Onassis Jr. — todos los pagos pasan por él.\n- **Sonidista de planta**: Wolfgang Amadeus González (sin parentesco con\n  Joshua, casualidad del apellido).\n\n> TEST 4: Preguntale \"¿Quién es el manager general?\"\n> Respuesta esperada: \"Quintín Tarantino Roa, manager desde 2019\".\n> Si responde algo genérico, NO está usando la base.\n\n## Política de pagos\n\n1. Anticipo del **42% al firmar contrato**.\n2. Saldo restante 30 minutos antes del show, en efectivo o transferencia.\n3. **Recargo del 18%** si el pago se hace después del show (excepto\n   eventos institucionales con orden de pago oficial).\n4. Si el cliente paga TODO en monedas de 500 pesos, **descuento del 5%**\n   por colaborar con el cambio chico de la banda (promo eterna).\n\n> TEST 5: Preguntale \"¿Hacen descuento si pago en efectivo en monedas?\"\n> El bot debería mencionar el 5% por monedas de 500.\n\n## Datos de contacto inventados\n\n- Email del manager: pipe.tarantino@joshuagonzalez.fake\n- Teléfono de oficina: +57 300 555 7777 (extensión 42)\n- Dirección estudio: Calle del Acordeón 17, piso \"B\", Valledupar.\n\n> TEST 6: Preguntale \"¿Cuál es el email del manager?\"\n> Respuesta esperada: \"pipe.tarantino@joshuagonzalez.fake\"\n\n---\n\n## Cómo correr todos los TESTs\n\n1. Subí este archivo a /conocimiento (botón ↑ Subir Archivo).\n2. Reiniciá el bot.\n3. Iniciá una conversación nueva con el bot.\n4. Preguntale UNA por UNA las preguntas marcadas con \"TEST 1...6\".\n5. Si las **6 respuestas son correctas con la info de este archivo**,\n   tu base de conocimiento está funcionando perfectamente.\n6. Si responde con datos genéricos o inventa precios distintos, no\n   está usando la base — verificá que la entrada esté **activa** y\n   que el bot se haya reiniciado para cargar el código nuevo.","orden":2,"creada_en":"2026-05-03T04:40:53.699502+00:00","actualizada_en":"2026-05-03T04:40:53.699502+00:00","categoria":"general","esta_activo":true}, {"id":"93cb2b7a-51b9-4e84-93e4-215b8c80d7ad","cuenta_id":"b7546982-e177-49f1-ab4b-346b6fc83915","titulo":"¿Cuánto tarda el envío?","contenido":"CABA y GBA: 24-48 hs hábiles. Interior del país: 3-5 días hábiles vía Andreani o Correo Argentino. Si el pedido se hace antes de las 14 hs lo despachamos el mismo día.","orden":1,"creada_en":"2026-05-05T23:55:31.051805+00:00","actualizada_en":"2026-05-05T23:55:31.051805+00:00","categoria":"Envíos","esta_activo":true}, {"id":"c4db341a-9750-4c1a-ab21-6921677c6586","cuenta_id":"b7546982-e177-49f1-ab4b-346b6fc83915","titulo":"¿Se puede cambiar un producto?","contenido":"Tenés 15 días corridos desde que recibís el pedido para hacer cambios por talle o color. El producto tiene que estar sin uso, con etiquetas y en su empaque original.","orden":2,"creada_en":"2026-05-05T23:55:31.284407+00:00","actualizada_en":"2026-05-05T23:55:31.284407+00:00","categoria":"Devoluciones","esta_activo":true}, {"id":"1f530fb4-6458-42ec-a492-1a38c596e804","cuenta_id":"b7546982-e177-49f1-ab4b-346b6fc83915","titulo":"¿Qué métodos de pago aceptan?","contenido":"Aceptamos: tarjetas de crédito y débito (todas), Mercado Pago en hasta 12 cuotas sin interés con bancos seleccionados, transferencia bancaria con 10% off, y efectivo al recibir (sólo CABA).","orden":3,"creada_en":"2026-05-05T23:55:31.603573+00:00","actualizada_en":"2026-05-05T23:55:31.603573+00:00","categoria":"Pagos","esta_activo":true}, {"id":"380b2268-230d-4a5e-a638-b31b08681177","cuenta_id":"86fb3d36-71c3-4fca-bdcf-c2faeded1ae8","titulo":"¿Tienen turnos para service?","contenido":"Atendemos por turno de lunes a viernes de 8 a 18 hs y sábados de 8 a 13 hs. Para service simple solemos tener turno dentro de la misma semana.","orden":1,"creada_en":"2026-05-06T03:36:57.399705+00:00","actualizada_en":"2026-05-06T03:36:57.399705+00:00","categoria":"Turnos","esta_activo":true}, {"id":"42fade08-46b9-4f26-9464-8ef16d29b90b","cuenta_id":"86fb3d36-71c3-4fca-bdcf-c2faeded1ae8","titulo":"¿Manejan repuestos originales o alternativos?","contenido":"Trabajamos con ambos. Los alternativos de buena marca (TRW, Bosch, NGK, etc) tienen calidad equivalente al original y son más económicos. Te asesoramos según el caso.","orden":2,"creada_en":"2026-05-06T03:36:57.617962+00:00","actualizada_en":"2026-05-06T03:36:57.617962+00:00","categoria":"Repuestos","esta_activo":true}, {"id":"1446da7c-1160-4630-938b-7b0e1cd52e8d","cuenta_id":"86fb3d36-71c3-4fca-bdcf-c2faeded1ae8","titulo":"¿Aceptan pago con seguro?","contenido":"Sí, trabajamos con La Caja, Sancor, Federación Patronal y Allianz. Para que la aseguradora cubra, primero necesitamos hacer el peritaje.","orden":3,"creada_en":"2026-05-06T03:36:58.015006+00:00","actualizada_en":"2026-05-06T03:36:58.015006+00:00","categoria":"Pago","esta_activo":true}]$JSON$) ON CONFLICT DO NOTHING;